import pandas as pd


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    if name in inputs:
        return inputs[name]
    lower_map = {k.lower(): k for k in inputs.keys()}
    if name.lower() in lower_map:
        return inputs[lower_map[name.lower()]]
    raise KeyError(name)


def run(inputs: dict) -> dict:
    postings = _get_input(inputs, 'POSTINGS').copy()

    # Legacy cursor ORDER BY account_id, post_date, post_seq (stable sort)
    postings = postings.sort_values(
        ['account_id', 'post_date', 'post_seq'],
        kind='mergesort'
    )

    posted_rows = []
    reject_rows = []

    prev_acct = None
    tot = 0.0
    rej = 0

    for _, r in postings.iterrows():
        acct = r['account_id']

        if acct != prev_acct:
            # flush previous account's reject count (including zero)
            if prev_acct is not None:
                reject_rows.append({
                    'account_id': prev_acct,
                    'reject_count': rej
                })
            tot = 0.0
            rej = 0
            prev_acct = acct

        qty = r['qty']
        price = r['unit_price']

        is_bad = (
            pd.isna(qty) or qty <= 0 or
            pd.isna(price) or price < 0
        )

        if is_bad:
            rej += 1
            # rejected row: skipped entirely, total unchanged
        else:
            v = qty * price
            tot = tot + v
            posted_rows.append({
                'account_id': acct,
                'post_seq': r['post_seq'],
                'post_date': r['post_date'],
                'post_value': v,
                'running_total': tot
            })

    # flush final account's reject count
    if prev_acct is not None:
        reject_rows.append({
            'account_id': prev_acct,
            'reject_count': rej
        })

    posted_totals = pd.DataFrame(
        posted_rows,
        columns=['account_id', 'post_seq', 'post_date', 'post_value', 'running_total']
    )
    reject_counts = pd.DataFrame(
        reject_rows,
        columns=['account_id', 'reject_count']
    )

    return {
        'posted_totals': posted_totals,
        'reject_counts': reject_counts
    }
